CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nickname VARCHAR(100), friends_json JSON, groups_json JSON, registered_at BIGINT NOT NULL DEFAULT 0, last_login_at BIGINT NOT NULL DEFAULT 0, rank_points INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, losses INT NOT NULL DEFAULT 0, draws INT NOT NULL DEFAULT 0, current_streak INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', INDEX idx_users_rank_points(rank_points), INDEX idx_users_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS matches (id BIGINT PRIMARY KEY, game_type VARCHAR(40) NOT NULL, player_a_id BIGINT, player_b_id BIGINT, winner_id BIGINT, result VARCHAR(20), rank_delta_a INT NOT NULL DEFAULT 0, rank_delta_b INT NOT NULL DEFAULT 0, board_log LONGTEXT, created_at BIGINT NOT NULL DEFAULT 0, finished_at BIGINT NOT NULL DEFAULT 0, INDEX idx_matches_finished_at(finished_at), INDEX idx_matches_player_a(player_a_id), INDEX idx_matches_player_b(player_b_id), CONSTRAINT fk_match_player_a FOREIGN KEY (player_a_id) REFERENCES users(id), CONSTRAINT fk_match_player_b FOREIGN KEY (player_b_id) REFERENCES users(id), CONSTRAINT fk_match_winner FOREIGN KEY (winner_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(80) NOT NULL, target VARCHAR(120), detail_text TEXT, created_at BIGINT NOT NULL, INDEX idx_admin_logs_created_at(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(500) NOT NULL, created_at BIGINT NOT NULL, last_login_at BIGINT NOT NULL DEFAULT 0, CONSTRAINT fk_admin_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
